import React, { useState, useEffect } from 'react';
import { useTheme } from './ThemeContext'; // Assuming a simple theme context for dark mode

interface User {
  id: number;
  name: string;
  score: number;
}

const mockUsers: User[] = [
  { id: 1, name: 'Alice', score: 9500 },
  { id: 2, name: 'Bob', score: 8200 },
  { id: 3, name: 'Charlie', score: 7800 },
  { id: 4, name: 'David', score: 7200 },
  { id: 5, name: 'Eve', score: 6800 },
  { id: 6, name: 'Frank', score: 6500 },
  { id: 7, name: 'Grace', score: 6000 },
  { id: 8, name: 'Hannah', score: 5500 },
  { id: 9, name: 'Ian', score: 5000 },
  { id: 10, name: 'Judy', score: 4500 },
];

const useRanking = (initialUsers: User[]): [User[], () => void] => {
  const [users, setUsers] = useState(initialUsers);

  const simulateRealtimeUpdate = () => {
    const randomIndex = Math.floor(Math.random() * users.length);
    const newScore = users[randomIndex].score + Math.floor(Math.random() * 100) + 1;
    const updatedUsers = users.map((user) =>
      user.id === users[randomIndex].id ? { ...user, score: newScore } : user
    );
    updatedUsers.sort((a, b) => b.score - a.score);
    setUsers(updatedUsers);
  };

  return [users, simulateRealtimeUpdate];
};

const RankingList: React.FC<{ users: User[] }> = ({ users }) => {
  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
      {users.map((user) => (
        <div
          key={user.id}
          className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-md flex items-center justify-between"
        >
          <div className="flex items-center">
            <div className="w-12 h-12 bg-gradient-to-r from-blue-500 to-purple-500 rounded-full flex items-center justify-center text-white font-bold">
              {user.id}
            </div>
            <div className="ml-4">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white">{user.name}</h3>
              <p className="text-gray-600 dark:text-gray-400">Score: {user.score}</p>
            </div>
          </div>
          <div className="flex items-center">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              className="h-6 w-6 text-gray-600 dark:text-gray-400"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6"
              />
            </svg>
          </div>
        </div>
      ))}
    </div>
  );
};

const App: React.FC = () => {
  const { isDarkMode, toggleTheme } = useTheme();
  const [users, simulateRealtimeUpdate] = useRanking(mockUsers);

  useEffect(() => {
    const interval = setInterval(simulateRealtimeUpdate, 5000);
    return () => clearInterval(interval);
  }, [simulateRealtimeUpdate]);

  return (
    <div
      className={`min-h-screen bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-white transition-colors duration-300 p-6`}
    >
