    [0, 0, 0],
  ];
  const J: number[][] = [
    [0, 0, 1],
    [1, 1, 1],
    [0, 0, 0],
  ];
  const Z: number[][] = [
    [1, 1, 0],
    [0, 1, 1],
    [0, 0, 0],
  ];
  const S: number[][] = [
    [0, 1, 1],
    [1, 1, 0],
    [0, 0, 0],
  ];

  const tetrominos = [T, I, O, L, J, Z, S];
  const colors = ['#00C4FF', '#FF6200', '#FFDE00', '#FF9900', '#80C1FF', '#FF006D', '#A0E75A'];

  type Position = { x: number; y: number };
  type Tetromino = { shape: number[][]; color: string; pos: Position };

  const createBoard = () => Array.from({ length: 20 }, () => Array(10).fill(0));

  const addTetromino = (board: number[][], tetromino: Tetromino): number[][] => {
    tetromino.shape.forEach((row, y) => {
      row.forEach((value, x) => {
        if (value) {
          board[tetromino.pos.y + y][tetromino.pos.x + x] = tetromino.color === '#00C4FF' ? 1 : 2;
        }
      });
    });
    return board;
  };

  const rotate = (matrix: number[][]): number[][] => {
    const M = matrix.length;
    const N = matrix[0].length;
    const result = Array.from({ length: N }, () => Array(M).fill(0));
    for (let i = 0; i < M; i++) {
      for (let j = 0; j < N; j++) {
        result[j][M - 1 - i] = matrix[i][j];
      }
    }
    return result;
  };

  const validMove = (board: number[][], tetromino: Tetromino, pos: Position): boolean => {
    for (let y = 0; y < tetromino.shape.length; y++) {
      for (let x = 0; x < tetromino.shape[y].length; x++) {
        if (tetromino.shape[y][x]) {
          const newY = tetromino.pos.y + y + pos.y;
          const newX = tetromino.pos.x + x + pos.x;
          if (newX < 0 || newX >= 10 || newY >= 20 || (newY >= 0 && board[newY][newX])) {
            return false;
          }
        }
      }
    }
    return true;
  };

  const clearLines = (board: number[][]): { newBoard: number[][]; linesCleared: number } => {
    let linesCleared = 0;
    const newBoard = board.filter(row => row.some(cell => !cell));
    linesCleared = 20 - newBoard.length;
    while (linesCleared) {
      newBoard.unshift(Array(10).fill(0));
      linesCleared--;
