    setCurrentPiece({ ...currentPiece, pos: { x: currentPiece.pos.x + dir.x, y: currentPiece.pos.y + dir.y } });
  };

  const rotatePiece = () => {
    const newShape = rotate(currentPiece.shape);
    if (!validMove(board, { ...currentPiece, shape: newShape }, { x: 0, y: 0 })) return;
    setCurrentPiece({ ...currentPiece, shape: newShape });
  };

  const freezeTetromino = () => {
    const newBoard = addTetromino(board, currentPiece);
