    setBoard(clearedBoard);
    setCurrentPiece(nextPiece);
    setNextPiece({ shape: tetrominos[Math.floor(Math.random() * tetrominos.length)], color: colors[Math.floor(Math.random() * colors.length)], pos: { x: 3, y: 0 } });
    if (!validMove(clearedBoard, nextPiece, { x: 0, y: 0 })) {
